package net.famzangl.minecraft.aimbow.aiming.Bow;
import net.minecraft.client.entity.EntityPlayerSP;
import net.minecraft.util.Vec3;
public final class ReverseBowSolver {private final float gravity,velocity;public ReverseBowSolver(float g,float v){gravity=g;velocity=v;}
 public Vec3 solve(EntityPlayerSP player,Vec3 target){if(player==null||target==null||velocity<.15F)return null;double dx=target.xCoord-player.posX,dz=target.zCoord-player.posZ,dist=Math.sqrt(dx*dx+dz*dz),dy=target.yCoord-(player.posY+player.getEyeHeight());if(dist<1E-6)return null;float low=-.99F,high=.99F;float lowY=yAt((float)Math.sqrt(1-low*low)*velocity,low*velocity,(float)dist),highY=yAt((float)Math.sqrt(1-high*high)*velocity,high*velocity,(float)dist);if((dy<Math.min(lowY,highY)-1)||(dy>Math.max(lowY,highY)+80))return null;for(int i=0;i<45;i++){float mid=(low+high)/2,h=(float)Math.sqrt(1-mid*mid),y=yAt(h*velocity,mid*velocity,(float)dist);if(Float.isNaN(y))return null;if(y>dy)high=mid;else low=mid;}float v=(low+high)/2,h=(float)Math.sqrt(Math.max(0,1-v*v));return new Vec3(dx/dist*h,v,dz/dist*h);}
 private float yAt(float mx,float my,float distance){float x=0,y=0;for(int i=0;i<200&&mx>1E-6;i++){if(x+mx>=distance)return y+(distance-x)/mx*my;x+=mx;y+=my;mx*=.99F;my=my*.99F-gravity;}return Float.NaN;}}
